"""Generate the macOS C API forwarding table from the selected Dawn SDK."""

import re
from pathlib import Path


def generate_loader(header, helpers):
    declarations = re.findall(r"^WGPU_EXPORT (.+?) (wgpu\w+)\((.*?)\) WGPU_FUNCTION_ATTRIBUTE;", header, re.MULTILINE)
    if not declarations:
        raise ValueError("Dawn SDK contains no WebGPU C API declarations")
    declarations += re.findall(r"^(WGPU\w+) (godot_webgpu_\w+)\((.*?)\);", helpers, re.MULTILINE)
    lines = [
        "// Generated by native_loader.py. Do not edit.",
        '#include "dawn_boundary.h"',
        "#include <dlfcn.h>",
        "static void *dawn_library = nullptr;",
    ]
    for result, name, parameters in declarations:
        arguments = (
            []
            if parameters == "void" or not parameters
            else [re.search(r"(\w+)$", part.strip()).group(1) for part in parameters.split(",")]
        )
        lines += [
            f"static decltype(&{name}) dawn_{name} = nullptr;",
            f'extern "C" {result} {name}({parameters}) {{ return dawn_{name}({", ".join(arguments)}); }}',
        ]
    lines += [
        "static bool load_native_dawn() {",
        "    if (dawn_library) { return true; }",
        "    if (__builtin_available(macOS 13.0, *)) {} else { return false; }",
        "    Dl_info module = {};",
        "    if (!dladdr(reinterpret_cast<const void *>(&load_native_dawn), &module) || !module.dli_fname) { return false; }",
        '    const CharString path = String::utf8(module.dli_fname).get_base_dir().path_join("libgodot_webgpu_dawn.dylib").utf8();',
        "    void *library = dlopen(path.get_data(), RTLD_NOW | RTLD_LOCAL);",
        "    if (!library) { return false; }",
    ]
    for _, name, _ in declarations:
        lines += [
            f'    dawn_{name} = reinterpret_cast<decltype(dawn_{name})>(dlsym(library, "{name}"));',
            f"    if (!dawn_{name}) {{ dlclose(library); return false; }}",
        ]
    lines += ["    dawn_library = library;", "    return true;", "}"]
    return "\n".join(lines) + "\n"


def build_loader(target, source, env):
    Path(str(target[0])).write_text(generate_loader(Path(str(source[0])).read_text(), Path(str(source[1])).read_text()))
